head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDBNF90000";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf90000.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_method", fn: function () { return String(String((dma_pageContext.get("method") ?? ""))); } },
        { childId: "ipt_itemCd", fn: function () { return String(String((dma_pageContext.get("itemCd") ?? ""))); } },
        { childId: "ipt_itemNm", fn: function () { return String(String((dma_pageContext.get("itemNm") ?? ""))); } },
        { childId: "__rb0", fn: function () { return String(String((dma_pageContext.get("typNm") ?? ""))) + "조회"; } },
        { childId: "ipt_searchWord", fn: function () { return String(String((dma_pageContext.get("searchWord") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        (($c.util.getComponent('ipt_searchWord')) && ($c.util.getComponent('ipt_searchWord')).setFocus ? ($c.util.getComponent('ipt_searchWord')).setFocus() : (($c.util.getComponent('ipt_searchWord')) && ($c.util.getComponent('ipt_searchWord')).focus ? ($c.util.getComponent('ipt_searchWord')).focus() : void 0)).select();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf90000.onpageload' }); }
};

// [A] 초기 목록 미해결 — 진입 키 instsearch 를 쓰는 tx 가 2개다(tx_fn_clickSearchList, tx_fn_enterSearchList)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name form_1_onsubmit
 * @description form_1 onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.form_1_onsubmit = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf90000.form_1_onsubmit' }); }
};

/**
 * @method
 * @name ipt_searchWord_onkeyup
 * @description ipt_searchWord 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_searchWord_onkeyup = async function(e){
    try {
        await scwin.enterSearchList();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf90000.ipt_searchWord_onkeyup' }); }
};

/**
 * @method
 * @name ipt_searchWord_onblur
 * @description ipt_searchWord 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_searchWord_onblur = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        $c.str.replaceAll(selfVar);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf90000.ipt_searchWord_onblur' }); }
};

/**
 * @method
 * @name btn_clickSearchList_onclick
 * @description btn_clickSearchList 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_clickSearchList_onclick = async function(e){
    try {
        await scwin.clickSearchList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf90000.btn_clickSearchList_onclick' }); }
};

/**
 * @method
 * @name grd_indList_oncellclick
 * @description grd_indList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_indList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_indList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_indList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.selectedCorp(r["cdId"], r["cdVal"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_indList.oncellclick' });
    }
};

/**
 * @method
 * @name btn_self_onclick
 * @description btn_self 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_self_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf90000.btn_self_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_clickSearchList
 * @description click Search List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_clickSearchList = async function () {
    const sbmOptions = {
        id: "tx_fn_clickSearchList",
        method: "post",
        action: "/common/InstSearch.do",
        ref: "dma_clickSearchListReq",
        target: "dlt_indList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_enterSearchList
 * @description enter Search List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_enterSearchList = async function () {
    const sbmOptions = {
        id: "tx_fn_enterSearchList",
        method: "post",
        action: "/common/InstSearch.do",
        ref: "dma_enterSearchListReq",
        target: "dlt_indList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name selectedCorp
 * @description selected Corp 처리
 * @param {*} co_cd co_cd
 * @param {*} co_nm co_nm
 * @returns {void}
 * @hidden N
 */
scwin.selectedCorp = function (co_cd, co_nm) {
    if ($c.str.getByteLength($c.util.getComponent("dma_clickSearchListReq").get("itemCd")) > 0) {
        ((scwin.opener().getComponentById($c.util.getComponent("dma_clickSearchListReq").get("itemCd"))) || { setValue: function () {} }).setValue(co_cd);
    }
    if ($c.str.getByteLength($c.util.getComponent("dma_clickSearchListReq").get("itemNm")) > 0) {
        ((scwin.opener().getComponentById($c.util.getComponent("dma_clickSearchListReq").get("itemNm"))) || { setValue: function () {} }).setValue(co_nm);
    }
    if ($c.util.getComponent("dma_clickSearchListReq").get("itemNm") === 'bnd_majagnt_com_nm') {
        if ((((scwin.opener().getComponentById('bnd_apct_tp_cd')) && (scwin.opener().getComponentById('bnd_apct_tp_cd')).getValue) ? (scwin.opener().getComponentById('bnd_apct_tp_cd')).getValue() : '') === '2') {
            ((scwin.opener().getComponentById('rep_majagnt_com_nm')) && (scwin.opener().getComponentById('rep_majagnt_com_nm')).setValue ? (scwin.opener().getComponentById('rep_majagnt_com_nm')).setValue(co_nm) : void (co_nm));
        }
    }
    $c.win.closePopup();
};

/**
 * @method
 * @name clickSearchList
 * @description click Search List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.clickSearchList = async function () {
    if ($c.str.getByteLength($c.util.getComponent('ipt_searchWord').getValue()) === 0) {
        $c.util.getComponent("ipt_searchWord").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        await $c.win.alert('검색조건을 입력바랍니다.');
        event.keyCode = 0;
        return false;
    } else {
        $c.util.getComponent('ipt_method').setValue("loadIndSearchData");
        await scwin.tx_fn_clickSearchList();
        event.keyCode = 0;
    }
};

/**
 * @method
 * @name enterSearchList
 * @description enter Search List 처리
 * @param {*} event event
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.enterSearchList = async function (event) {
    if (event && $c.util.getKeyCode(event) === 13) {
        event.keyCode = 0;
        if ($c.str.getByteLength($c.util.getComponent('ipt_searchWord').getValue()) === 0) {
            $c.util.getComponent("ipt_searchWord").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
            await $c.win.alert('검색조건을 입력바랍니다.');
            return false;
        } else {
            $c.str.replaceAll($c.util.getComponent('ipt_searchWord'));
            $c.util.getComponent('ipt_method').setValue("loadIndSearchData");
            await scwin.tx_fn_enterSearchList();
        }
    }
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};
